"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[62861],{6738:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>c,frontMatter:()=>i,metadata:()=>a,toc:()=>d});var o=h(31085),n=h(71184);const i={sidebar_position:20,slug:"/bible/Ezechiel/Ezechiel_20",title:"Ezechiel 20",hide_table_of_contents:!0},s="Ezechiel",a={id:"bible/Ezechiel/Ezechiel 20",title:"Ezechiel 20",description:"Chapter 20",source:"@site/docs/bible/Ezechiel/Ezechiel 20.md",sourceDirName:"bible/Ezechiel",slug:"/bible/Ezechiel/Ezechiel_20",permalink:"/docs/bible/Ezechiel/Ezechiel_20",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Ezechiel/Ezechiel 20.md",tags:[],version:"current",sidebarPosition:20,frontMatter:{sidebar_position:20,slug:"/bible/Ezechiel/Ezechiel_20",title:"Ezechiel 20",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Ezechiel 19",permalink:"/docs/bible/Ezechiel/Ezechiel_19"},next:{title:"Ezechiel 21",permalink:"/docs/bible/Ezechiel/Ezechiel_21"}},r={},d=[{value:"Chapter 20",id:"chapter-20",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,n.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"ezechiel",children:"Ezechiel"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-20",children:"Chapter 20"}),"\n",(0,o.jsx)(t.p,{children:"God refuses to answer the ancients of Israel inquiring by the prophet: but by him setteth his benefits before their eyes, and their heinous sins:  threatening yet greater punishments:  but still mixed with mercy."}),"\n",(0,o.jsx)(h,{verse:1,children:"And it came to pass in the seventh year, in the fifth month, the tenth day of the month: there came men of the ancients of Israel to inquire of the Lord, and they sat before me."}),"\n",(0,o.jsx)(h,{verse:2,children:"And the word of the Lord came to me, saying:"}),"\n",(0,o.jsx)(h,{verse:3,children:"Son of man, speak to the ancients of Israel and say to them: Thus saith the Lord God: Are you come to inquire of me? As I live, I will not answer you, saith the Lord God."}),"\n",(0,o.jsx)(h,{verse:4,children:"If thou judgest them, if thou judgest, O son of man, declare to them the abominations of their fathers."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: If thou judgest them...Or, if thou wilt enter into the cause and plead against them."})}),"\n",(0,o.jsx)(h,{verse:5,children:"And say to them: Thus saith the Lord God: In the day when I chose Israel, and lifted up my hand for the race of the house of Jacob: and appeared to them in the land of Egypt, and lifted up my hand for them, saying: I am the Lord your God:"}),"\n",(0,o.jsx)(h,{verse:6,children:"In that day I lifted up my hand for them to bring them out of the land of Egypt, into a land which I had provided for them, flowing with milk and honey, which excelled amongst all lands."}),"\n",(0,o.jsx)(h,{verse:7,children:"And I said to them: Let every man cast away the scandals of his eyes, and defile not yourselves with the idols of Egypt: I am the Lord your God."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Scandals, etc...Offensiones. That is, the abominations or idols, to the worship of which they were allured by their eyes."})}),"\n",(0,o.jsx)(h,{verse:8,children:"But they provoked me, and would not hearken to me: they did not every man cast away the abominations of his eyes, neither did they forsake the idols of Egypt: and I said I would pour out my indignation upon them, and accomplish my wrath against them in the midst of the land of Egypt."}),"\n",(0,o.jsx)(h,{verse:9,children:"But I did otherwise for my name's sake, that it might not be violated before the nations, in the midst of whom they were, and among whom I made myself known to them, to bring them out of the land of Egypt."}),"\n",(0,o.jsx)(h,{verse:10,children:"Therefore I brought them out from the land of Egypt, and brought them into the desert."}),"\n",(0,o.jsx)(h,{verse:11,children:"And I gave them my statutes, and I shewed them my judgments, which if a man do, he shall live in them."}),"\n",(0,o.jsx)(h,{verse:12,children:"Moreover I gave them also my sabbaths, to be a sign between me and them: and that they might know that I am the Lord that sanctify them."}),"\n",(0,o.jsx)(h,{verse:13,children:"But the house of Israel provoked me in the desert: they walked not in my statutes, and they cast away my judgments, which if a man do he shall live in them: and they grievously violated my sabbaths. I said therefore that I would pour out my indignation upon them in the desert, and would consume them."}),"\n",(0,o.jsx)(h,{verse:14,children:"But I spared them for the sake of my name, lest it should be profaned before the nations, from which I brought them out, in their sight."}),"\n",(0,o.jsx)(h,{verse:15,children:"So I lifted up my hand over them in the desert, not to bring them into the land which I had given them flowing with milk and honey, the best of all lands."}),"\n",(0,o.jsx)(h,{verse:16,children:"Because they cast off my judgments, and walked not in my statutes, and violated my sabbaths: for their heart went after idols."}),"\n",(0,o.jsx)(h,{verse:17,children:"Yet my eye spared them, so that I destroyed them not: neither did I consume them in the desert."}),"\n",(0,o.jsx)(h,{verse:18,children:"And I said to their children in the wilderness: Walk not in the statutes of your fathers, and observe not their judgments, nor be ye defiled with their idols:"}),"\n",(0,o.jsx)(h,{verse:19,children:"I am the Lord your God: walk ye in my statutes, and observe my judgments, and do them."}),"\n",(0,o.jsx)(h,{verse:20,children:"And sanctify my sabbaths, that they may be a sign between me and you: and that you may know that I am the Lord your God."}),"\n",(0,o.jsx)(h,{verse:21,children:"But their children provoked me, they walked not in my commandments, nor observed my judgments to do them: which if a man do, he shall live in them: and they violated my sabbaths: and I threatened to pour out my indignation upon them, and to accomplish my wrath in them in the desert."}),"\n",(0,o.jsx)(h,{verse:22,children:"But I turned away my hand, and wrought for my name's sake, that it might not be violated before the nations, out of which I brought them forth in their sight."}),"\n",(0,o.jsx)(h,{verse:23,children:"Again I lifted up my hand upon them in the wilderness, to disperse them among the nations, and scatter them through the countries:"}),"\n",(0,o.jsx)(h,{verse:24,children:"Because they had not done my judgments, and had cast off my statutes, and had violated my sabbaths, and their eyes had been after the idols of their fathers."}),"\n",(0,o.jsx)(h,{verse:25,children:"Therefore I also gave them statutes that were not good, and judgments, in which they shall not live."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Statutes that were not good, etc...Viz., the laws and ordinances of their enemies; or those imposes upon them by that cruel tyrant the devil, to whose power they were delivered up for their sins."})}),"\n",(0,o.jsx)(h,{verse:26,children:"And I polluted them in their own gifts, when they offered all that opened the womb, for their offences: and they shall know that I am the Lord."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: I polluted them, etc...That is, I gave them up to such blindness in punishment of their offences, as to pollute themselves with the blood of all their firstborn, whom they offered up to their idols in compliance with their wicked devices."})}),"\n",(0,o.jsx)(h,{verse:27,children:"Wherefore speak to the house of Israel, O son of man, and say to them: Thus saith the Lord God: Moreover in this also your fathers blaspheme me, when they had despised and contemned me;"}),"\n",(0,o.jsx)(h,{verse:28,children:"And I had brought them into the land, for which I lifted up my hand to give it them: they saw every high hill, and every shady tree, and there they sacrificed their victims: and there they presented the provocation of their offerings, and there they set their sweet odours, and poured forth their libations."}),"\n",(0,o.jsx)(h,{verse:29,children:"And I said to them: What meaneth the high place to which you go? and the name thereof was called High-place even to this day."}),"\n",(0,o.jsx)(h,{verse:30,children:"Wherefore say to the house of Israel: Thus saith the Lord God: Verily, you are defiled in the way of your fathers, and you commit fornication with their abominations."}),"\n",(0,o.jsx)(h,{verse:31,children:"And you defile yourselves with all your idols unto this day, in the offering of your gifts, when you make your children pass through the fire: and shall I answer you, O house of Israel? As I live, saith the Lord God, I will not answer you."}),"\n",(0,o.jsx)(h,{verse:32,children:"Neither shall the thought of your mind come to pass, by which you say: We will be as the Gentiles, and as the families of the earth, to worship stocks and stones."}),"\n",(0,o.jsx)(h,{verse:33,children:"As I live, saith the Lord God, I will reign over you with a strong hand, and with a stretched out arm, and with fury poured out."}),"\n",(0,o.jsx)(h,{verse:34,children:"And I will bring you out from the people, and I will gather you out of the countries, in which you are scattered, I will reign over you with a strong hand and with a stretched out arm, and with fury poured out."}),"\n",(0,o.jsx)(h,{verse:35,children:"And I will bring you into the wilderness of people, and there will I plead with you face to face."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: The wilderness of people...That is, a desert in which there are no people."})}),"\n",(0,o.jsx)(h,{verse:36,children:"As I pleaded against your fathers in the desert of the land of Egypt; even so will I judge you, saith the Lord God."}),"\n",(0,o.jsx)(h,{verse:37,children:"And I will make you subject to my sceptre, and will bring you into the bands of the covenant."}),"\n",(0,o.jsx)(h,{verse:38,children:"And I will pick out from among you the transgressors, and the wicked, and will bring them out of the land where they sojourn, and they shall not enter into the land of Israel: and you shall know that I am the Lord."}),"\n",(0,o.jsx)(h,{verse:39,children:"And as for you, O house of Israel: thus saith the Lord God: Walk ye every one after your idols, and serve them. But if in this also you hear me not, but defile my holy name any more with your gifts, and with your idols;"}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Walk ye every one, etc...It is not an allowance, much less a commandment to serve idols; but a figure of speech, by which God would have them to understand that if they would walk after their idols, they must not pretend to serve him at the same time: for that he would by no means suffer such a mixture of worship."})}),"\n",(0,o.jsx)(h,{verse:40,children:"In my holy mountain, in the high mountain of Israel, saith the Lord God, there shall all the house of Israel serve me; all of them I say, in the land in which they shall please me, and there will I require your firstfruits, and the chief of your tithes with all your sanctifications."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: In my holy mountain, etc...The foregoing verse, to make the sense complete, must be understood so as to condemn and reject that mixture of worship which the Jews then followed. In this verse, God promises to the true Israelites, especially to those of the Christian church, that they shall serve him in another manner, in his holy mountain, the spiritual Sion: and shall by accepted of by him."})}),"\n",(0,o.jsx)(h,{verse:41,children:"I will accept of you for an odour of sweetness, when I shall have brought you out from the people, and shall have gathered you out of the lands into which you are scattered, and I will be sanctified in you in the sight of the nations."}),"\n",(0,o.jsx)(h,{verse:42,children:"And you shall know that I am the Lord, when I shall have brought you into the land of Israel, into the land for which I lifted up my hand to give it to your fathers."}),"\n",(0,o.jsx)(h,{verse:43,children:"And there you shall remember your ways, and all your wicked doings with which you have been defiled; and you shall be displeased with yourselves in your own sight, for all your wicked deeds which you committed."}),"\n",(0,o.jsx)(h,{verse:44,children:"And you shall know that I am the Lord, when I shall have done well by you for my own name's sake, and not according to your evil ways, nor according to your wicked deeds, O house of Israel, saith the Lord God."}),"\n",(0,o.jsx)(h,{verse:45,children:"And the word of the Lord came to me, saying:"}),"\n",(0,o.jsx)(h,{verse:46,children:"Son of man, set thy face against the way of the south, and drop towards the south, and prophesy against the forest of the south field."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Of the south...Jerusalem lay towards the south of Babylon, (where the prophet then was,) and is here called the forest of the south field, and is threatened with utter desolation."})}),"\n",(0,o.jsx)(h,{verse:47,children:"And say to the south forest: Hear the word of the Lord: Thus saith the Lord God: Behold I will kindle a fire in thee, and will burn in thee every green tree, and every dry tree: the flame of the fire shall not be quenched: and every face shall be burned in it, from the south even to the north."}),"\n",(0,o.jsx)(h,{verse:48,children:"And all flesh shall see, that I the Lord have kindled it, and it shall not be quenched."}),"\n",(0,o.jsx)(h,{verse:49,children:"And I said: Ah, ah, ah, O Lord God: they say of me: Doth not this man speak by parables?"})]})}function c(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>s,x:()=>a});var o=h(14041);const n={},i=o.createContext(n);function s(e){const t=o.useContext(i);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);